UPDATE spotlights
SET releases = $json$[{"year": "2009", "title": "The Spoils", "artist": "Zola Jesus", "note": "An early release that helped establish the label's dark electronic sound. Nika Roza Danilova's classically trained vocals sit over sparse, layered arrangements.", "badge": null}, {"year": "2011", "title": "Leave Home", "artist": "The Men", "note": "A raw, guitar-driven post-punk record from the Brooklyn band and the label's early roster. It captures Sacred Bones' connection to the New York underground scene.", "badge": null}, {"year": "2014", "title": "Love", "artist": "Amen Dunes", "note": "Damon McMahon's psych-folk songwriting with more developed arrangements. The album broadens the picture of Sacred Bones beyond its darker electronic and post-punk releases.", "badge": null}, {"year": "2015", "title": "Apocalypse, girl", "artist": "Jenny Hval", "note": "Experimental pop that brings together songwriting, poetry, and performance art. Hval's release shows the label's interest in work that moves beyond conventional song structures.", "badge": null}, {"year": "2015", "title": "Lost Themes", "artist": "John Carpenter, Cody Carpenter & Daniel Davies", "note": "Instrumental synthesizer music made outside a film commission. Its cinematic atmosphere connects Carpenter's soundtrack work with the label's catalogue.", "badge": null}, {"year": "2017", "title": "Contact", "artist": "Pharmakon", "note": "Margaret Chardiet's project explores industrial and experimental electronics through dense sound and intense vocal performances.", "badge": null}, {"year": "2020", "title": "Etazhi", "artist": "Molchat Doma", "note": "Sacred Bones' North American reissue of the Belarusian trio's 2018 album. Its post-punk arrangements, synthesizer bass, and Russian-language vocals brought the record to a wider audience.", "badge": "Reissue"}, {"year": "2026", "title": "Marathon", "artist": "Maria BC", "note": "Maria BC's third studio album and second release for Sacred Bones. It moves between intimate songwriting and more driving, layered arrangements, with themes of endurance, resistance, and survival.", "badge": null}]$json$::jsonb
WHERE name = 'Sacred Bones Records' AND month = '2026-11';
